export interface Users {
  /**
   * @displayName Users
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Email ID
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  emailID: string;
  /**
   * @displayName Added Date
   */
  addedDate?: string;
  /**
   * @displayName Company
   */
  company?: string;
  /**
   * @displayName Department
   */
  department?: string;
  /**
   * @displayName Is Active
   * @validationRule Required for create/update operations
   */
  isActive: boolean;
  /**
   * @displayName Job Title
   */
  jobTitle?: string;
  /**
   * @displayName Last Login Date
   */
  lastLoginDate?: string;
  /**
   * @displayName Permissions
   */
  permissions?: string;
  /**
   * @displayName Phone Number
   */
  phoneNumber?: string;
  /**
   * @displayName Profile Image URL
   */
  profileImageURL?: string;
  /**
   * @displayName Role
   * @validationRule Required for create/update operations
   */
  role: string;
  /**
   * @displayName UserName
   * @validationRule Required for create/update operations
   */
  userName: string;
}

export const _Users = 'Users' as const;